	if r.Streak != 0 || r.Seen != 2 || r.Correct != 1 {
		t.Fatalf("after a miss: %+v", r)
	}
	if want := epoch.Add(25*time.Hour + 10*time.Minute); !r.DueAt.Equal(want) {
